/**
 * Medusa's icons clip their drawing with `clip-path="url(#a)"`, and every
 * icon defines its own `<clipPath id="a">`. With several icons on a page the
 * browser resolves `#a` to the first one in the document, which can belong to
 * another, differently placed or hidden icon, and the icon comes out cut
 * (e.g. the top of the envelope missing). The clip is only the icon's own
 * 15×15 box, so inside our tiles it is switched off.
 */
export const ICON_TILE_CLASS = "bitshaft-icon-tile"

const STYLE_ID = "bitshaft-icon-tile-style"

/** Adds the one CSS rule once per page. */
export function ensureIconTileStyle(): void {
  if (typeof document === "undefined" || document.getElementById(STYLE_ID)) return
  const style = document.createElement("style")
  style.id = STYLE_ID
  style.textContent = `.${ICON_TILE_CLASS} [clip-path] { clip-path: none; }`
  document.head.appendChild(style)
}
